package ru.evolenta.pgs.worker;
import java.util.*;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import static ru.evolenta.pgs.worker.Util.*;

/** Resumable trade import; each create has its own durable intent and stable identity. */
public final class TradeImportOperations {
    public static final String WORKER_CONTRACT="pgs-trade-external-v1";
    private final CheckpointStore journal;private final Operations.Lease lease;private final boolean writes;private final String ui;
    public TradeImportOperations(CheckpointStore journal,Operations.Lease lease,boolean writes,String ui){this.journal=journal;this.lease=lease;this.writes=writes;this.ui=ui.replaceAll("/+$","");}
    public static String inputHash(Map<String,Object>d){return hash(obj("sheets",d.get("sheets"),"file",d.get("file"),"context",d.get("context"),"validationVersion",d.get("validationVersion"),"dataType",d.get("dataType"),"parserVersion",d.get("parserVersion"),"confirmationFingerprint",d.get("confirmationFingerprint"),"workerValidationKey",d.get("workerValidationKey")));}
    public Map<String,Object> apply(Context c)throws Exception{
        if(!writes)throw new IllegalStateException("Реестровые изменения отключены настройкой worker.writesEnabled");
        if(ui.isEmpty()||ui.contains("REPLACE")||!ui.startsWith("https://"))throw new IllegalArgumentException("Настройте HTTPS worker.uiBaseUrl до применения импорта");
        TradeGuard guard=new TradeGuard(c,true);Map<String,Object>d=copy(map(first(c.appeal.get("importDraft"),c.sub.get("rbuImportDraft"))));String fileId=clean(at(d,"file.id")),fileHash=clean(at(d,"file.sha256"));
        if(!fileId.equals(clean(first(at(c.appeal,"importFile._id"),at(c.appeal,"importFile.id"),at(c.appeal,"importFile.fileId")))))throw new IllegalArgumentException("В деле выбран другой файл; повторите валидацию");
        if(!Arrays.asList("VALIDATED","APPLYING","APPLIED").contains(clean(d.get("status")))||bool(d.get("validationBlocked"))||integer(d.get("validRows"))<=0||!ru.evolenta.pgs.worker.trade.TradeDomain.VALIDATION_VERSION.equals(d.get("validationVersion"))||!fileHash.equals(clean(d.get("validatedFileSha256"))))throw new IllegalArgumentException("Нет актуального допустимого результата валидации");
        if(integer(d.get("invalidRows"))!=0||!"rbu-trade-4.0".equals(d.get("parserVersion"))||!new ru.evolenta.pgs.worker.trade.TradeDomain(c).selectedType().equals(d.get("dataType")))throw new IllegalArgumentException("Изменён вид данных или имеются ошибочные строки; повторите валидацию");
        Object confirm=at(c.xsd,"rbuImportConfirmation.confirmApply");if(!bool(confirm))throw new IllegalArgumentException("Подтвердите миграцию");
        String confirmation=clean(d.get("confirmationFingerprint"));if(!confirmation.matches("[0-9a-f]{64}")||!confirmation.equals(clean(at(c.xsd,"rbuImportConfirmation.confirmationFingerprint"))))throw new IllegalArgumentException("Подтверждение относится к другой проверке файла");
        if(!id(guard.organization).equals(clean(at(d,"context.organization._id")))||!key(at(d,"context.region")).equals(key(guard.region.get("regionName")))||!key(at(d,"context.municipality")).equals(key(guard.municipality.get("municipalityName"))))throw new IllegalArgumentException("Контекст изменился после проверки");
        String validationKey=clean(d.get("workerValidationKey"));Map<String,Object>validated=journal.read(validationKey);if(!c.command.processId.equals(validated.get("processId"))||!c.command.mainId.equals(validated.get("appealId"))||!inputHash(d).equals(validated.get("inputHash")))throw new IllegalArgumentException("Серверный снимок валидации отсутствует или изменён; выполните проверку повторно");
        if(validated.get("draft") instanceof Map){d=map(validated.get("draft"));if(bool(d.get("validationBlocked")))throw new IllegalArgumentException("Серверная валидация заблокировала файл");}
        lease.check();if(!fileHash.equals(sha(c.api.download(fileId,XlsxReader.MAX_FILE))))throw new IllegalArgumentException("Содержимое файла изменилось после проверки");
        String runKey=hash(obj("process",c.command.processId,"mainId",c.command.mainId,"file",fileHash,"operation","IMPORT"));Map<String,Object>state=journal.read(runKey);if(state.isEmpty()){state=obj("status","APPLYING","createdAt",now(),"cursor",0,"processId",c.command.processId,"appealId",c.command.mainId,"workerContract",WORKER_CONTRACT,"organizationId",id(guard.organization));journal.save(runKey,state);}String started=clean(state.get("createdAt"));if(Arrays.asList("RESULT_READY","APPLIED").contains(clean(state.get("status")))&&!maps(state.get("recordJournal")).isEmpty())return persistReady(c,runKey,state);
        List<Map<String,Object>>plan=plan(c,d,guard,started);if(plan.size()>2500)throw new IllegalArgumentException("Превышен лимит 2500 физических записей");String planHash=hash(plan);if(present(state.get("planHash"))&&!planHash.equals(state.get("planHash")))throw new IllegalArgumentException("План импорта изменился; продолжение запрещено");state.put("planHash",planHash);journal.save(runKey,state);
        Map<String,Map<String,Object>>created=new LinkedHashMap<String,Map<String,Object>>();int cursor=integer(state.get("cursor")),end=Math.min(plan.size(),cursor+50);if(cursor<0||cursor>plan.size())throw new IllegalArgumentException("Повреждён cursor импорта");
        // Resolve already-created dependencies without recreating them.
        for(int i=0;i<cursor;i++){Map<String,Object>item=plan.get(i);Map<String,Object>saved=journal.read(clean(item.get("operationKey")));if(!"COMPLETED".equals(saved.get("status")))throw new IllegalStateException("Контрольная точка записи отсутствует");Map<String,Object> actual=c.api.find(clean(item.get("collection")),clean(saved.get("_id")));if(actual.isEmpty()||!clean(saved.get("guid")).equals(clean(actual.get("guid")))||!clean(saved.get("businessHash")).equals(businessHash(actual)))throw new IllegalStateException("Ранее созданная запись изменена; продолжение импорта остановлено");created.put(clean(item.get("ref")),saved);}
        for(int i=cursor;i<end;i++){lease.check();Map<String,Object>item=plan.get(i);Map<String,Object>payload=map(resolve(item.get("payload"),created));Map<String,Object>saved=create(c,clean(item.get("collection")),clean(item.get("operationKey")),payload);saved.putAll(obj("sheetCode",item.get("sheetCode"),"sheetName",item.get("sheetName"),"rowNumber",item.get("rowNumber"),"recordPart",item.get("recordPart")));journal.save(clean(item.get("operationKey")),saved);created.put(clean(item.get("ref")),saved);state.put("cursor",i+1);journal.save(runKey,state);}
        boolean more=end<plan.size();if(!more){state.put("status","APPLIED");state.put("completedAt",now());journal.save(runKey,state);}
        List<Object>records=new ArrayList<Object>();Set<String>sourceRows=new HashSet<String>();Map<String,Object>byCollection=obj();for(Map<String,Object>item:plan){Map<String,Object>saved=created.get(clean(item.get("ref")));if(saved==null)continue;String collection=clean(item.get("collection"));Map<String,Object>record=c.api.find(collection,clean(saved.get("_id")));if(record.isEmpty())throw new IllegalStateException("Созданная запись исчезла: "+collection+"/"+saved.get("_id"));if(!clean(saved.get("guid")).equals(clean(record.get("guid")))||!clean(saved.get("businessHash")).equals(businessHash(record)))throw new IllegalStateException("Созданная запись изменена во время импорта: "+collection+"/"+id(record));records.add(obj("collection",collection,"_id",id(record),"guid",record.get("guid"),"sheetCode",item.get("sheetCode"),"sheetName",item.get("sheetName"),"rowNumber",item.get("rowNumber"),"recordPart",item.get("recordPart"),"createdAt",started,"operationKey",item.get("operationKey"),"businessHash",businessHash(record),"unitId",first(at(record,"unit.id"),record.get("dictionaryUnitId"))));sourceRows.add(item.get("sheetCode")+":"+item.get("rowNumber"));byCollection.put(collection,integer(byCollection.get(collection))+1);}
        d.put("status",more?"APPLYING":"APPLIED");d.put("batchProgress",obj("status",more?"PROCESSING":"COMPLETED","nextOffset",end,"totalRecords",plan.size(),"fileSha256",fileHash,"updatedAt",now()));Map<String,Object>result=copy(map(c.sub.get("rbuImportResult")));result.remove("rbuImportConfirmation");result.putAll(obj("processingStatus",more?"Миграция выполняется":"Миграция завершена","applicationStatus",d.get("status"),"createdRows",sourceRows.size(),"reusedRows",0,"skippedRows",more?0:Math.max(0,integer(d.get("validRows"))-sourceRows.size()),"processedAt",now()));Map<String,Object>summary=obj("workerContract",WORKER_CONTRACT,"workerRunKey",runKey,"status",d.get("status"),"dataType",d.get("dataType"),"recordCount",records.size(),"createdRows",sourceRows.size(),"recordsByCollection",byCollection,"updatedAt",now());if(!more)summary.put("completedAt",state.get("completedAt"));Map<String,Object>publicDraft=Operations.compactDraft(d);
        Map<String,Object> variables=obj("rbuApplicationStatus",d.get("status"),"rbuCreatedRows",sourceRows.size(),"rbuReusedRecords",0,"rbuSkippedRows",result.get("skippedRows"),"rbuApplyHasMoreBatches",more,"rbuApplyRowCursor",end,"rbuApplyRejected",false,"rbuApplyError","");
        state.putAll(obj("status",more?"APPLYING":"RESULT_READY","recordJournal",records,"readyDraft",publicDraft,"readyResult",result,"readySummary",summary,"resultVariables",variables));journal.save(runKey,state);return persistReady(c,runKey,state);
    }
    private Map<String,Object> persistReady(Context c,String runKey,Map<String,Object> state)throws Exception{
        Map<String,Object> draft=map(state.get("readyDraft")),result=map(state.get("readyResult"));
        lease.check();c.saveAppeal(obj("importDraft",draft,"applicationStatus",draft.get("status"),"migrationLog",result.get("migrationLog")));c.saveResult(draft,result);c.saveSub(obj("migrationCreatedRecords",state.get("recordJournal"),"tradeMigrationSummary",state.get("readySummary")));
        if("RESULT_READY".equals(state.get("status"))){state.put("status","APPLIED");journal.save(runKey,state);}return map(state.get("resultVariables"));
    }
    private List<Map<String,Object>> plan(Context c,Map<String,Object>d,TradeGuard guard,String started)throws Exception{
        List<Map<String,Object>> out=new ArrayList<>();
        for(ru.evolenta.pgs.worker.trade.core.PlannedEntity entity:new ru.evolenta.pgs.worker.trade.TradeDomain(c).plan(d,started)){
            Map<String,Object> record=new LinkedHashMap<>(entity.data());Map<String,Object> source=copy(map(record.get("migrationSource")));
            String key=hash(obj("process",c.command.processId,"appeal",c.command.mainId,"file",at(d,"file.sha256"),"collection",entity.collection(),"ref",entity.key()));
            source.put("workerContract",WORKER_CONTRACT);source.put("operationKey",key);record.put("migrationSource",source);
            out.add(obj("ref",entity.key(),"operationKey",key,"collection",entity.collection(),"sheetCode",source.get("sheetCode"),"sheetName",source.get("sheetName"),"rowNumber",source.get("rowNumber"),"recordPart",source.get("recordPart"),"payload",record));
        }
        return out;
    }
    private Object resolve(Object value,Map<String,Map<String,Object>>created){
        if(value instanceof ru.evolenta.pgs.worker.trade.core.EntityReference reference){Map<String,Object> record=created.get(reference.key());if(record==null)throw new IllegalStateException("Не создана зависимость: "+reference.key());return record.get(reference.field());}
        if(value instanceof Map){Map<String,Object> m=obj();for(Map.Entry<String,Object> e:map(value).entrySet())m.put(e.getKey(),resolve(e.getValue(),created));return m;}
        if(value instanceof List){List<Object> items=new ArrayList<>();for(Object item:list(value))items.add(resolve(item,created));return items;}
        return value;
    }
    private Map<String,Object>create(Context c,String collection,String key,Map<String,Object>payload)throws Exception{
        String expectedHash=businessHash(payload);Map<String,Object> saved=journal.read(key);
        if(!saved.isEmpty()&&!expectedHash.equals(clean(saved.get("businessHash"))))throw new IllegalStateException("Контрольная точка CREATE относится к другому содержимому записи");
        List<Map<String,Object>> found=c.api.search(collection,Arrays.asList(Context.filter("migrationSource.operationKey",key)),0,2);
        if(found.size()>1)throw new IllegalStateException("Дубли operationKey, необходим ручной разбор");
        if(found.size()==1){if(saved.isEmpty())throw new IllegalStateException("Найдена запись без доверенного CREATE intent worker; автоматическое присвоение запрещено");return completeCreate(c,collection,key,payload,found.get(0),expectedHash);}
        if(!saved.isEmpty())throw new IllegalStateException("Неопределённый результат ранее начатого CREATE: "+collection+". Повторный CREATE запрещён до сверки");
        lease.check();journal.save(key,obj("status","CREATE_PENDING","collection",collection,"guid",payload.get("guid"),"operationKey",key,"businessHash",expectedHash,"startedAt",now()));
        Map<String,Object> created=c.api.create(collection,payload);if(id(created).isEmpty())throw new IllegalStateException("CREATE не вернул идентификатор; повтор запрещён до сверки");
        Map<String,Object> record=c.api.find(collection,id(created));if(record.isEmpty())throw new IllegalStateException("Созданная запись не доступна для проверки; CREATE intent сохранён");
        return completeCreate(c,collection,key,payload,record,expectedHash);
    }
    private Map<String,Object>completeCreate(Context c,String collection,String key,Map<String,Object>payload,Map<String,Object>record,String expectedHash)throws Exception{
        String owner=clean(first(at(record,"unit.id"),record.get("dictionaryUnitId"))),expectedOwner=clean(first(at(payload,"unit.id"),payload.get("dictionaryUnitId")));
        if(!c.command.mainId.equals(clean(at(record,"migrationSource.appealId")))||!clean(at(payload,"migrationSource.sourceFileSha256")).equals(clean(at(record,"migrationSource.sourceFileSha256")))||!key.equals(clean(at(record,"migrationSource.operationKey")))||!clean(payload.get("guid")).equals(clean(record.get("guid")))||!owner.equals(expectedOwner)||!expectedHash.equals(businessHash(record)))throw new IllegalStateException("Конфликт идентичности или содержимого импортируемой записи: "+collection+"/"+id(record));
        Map<String,Object> done=obj("status","COMPLETED","collection",collection,"_id",id(record),"guid",record.get("guid"),"operationKey",key,"businessHash",expectedHash,"unitId",owner);journal.save(key,done);return done;
    }
    public static String businessHash(Map<String,Object>record){Map<String,Object>m=copy(record);for(String name:Arrays.asList("_id","auid","guid","dateCreation","dateLastModification","lastChangedAt","userCreation","userLastModification","lastChangedByAppealId","entityType"))m.remove(name);return hash(canonicalNumbers(m));}
    // JSON numbers can be stored as 7800.0 after being sent as 7.8E+3; their value is unchanged.
    private static Object canonicalNumbers(Object value){if(value instanceof Number)return new BigDecimal(value.toString()).stripTrailingZeros();if(value instanceof Map){Map<String,Object> out=obj();map(value).forEach((name,item)->out.put(name,canonicalNumbers(item)));return out;}if(value instanceof List){List<Object> out=new ArrayList<>();for(Object item:list(value))out.add(canonicalNumbers(item));return out;}return value;}
    public Map<String,Object>finalizeImport(Context c)throws Exception{Map<String,Object>summary=map(c.sub.get("tradeMigrationSummary"));String runKey=hash(obj("process",c.command.processId,"mainId",c.command.mainId,"file",at(c.appeal,"importDraft.file.sha256"),"operation","IMPORT"));if(!"APPLIED".equals(journal.read(runKey).get("status")))throw new IllegalStateException("Нет серверной контрольной точки завершённого импорта");if(!"APPLIED".equals(summary.get("status")))throw new IllegalStateException("Импорт не завершён; журнал не может быть финализирован");return obj("rbuApplicationStatus","APPLIED","rbuApplyHasMoreBatches",false,"rbuCreatedRows",integer(summary.get("createdRows")));}
}
